import json,re
h=open\('viz.html'\).read\(\)
def grab\(name\):
    i=h.index\('const %s = '%name\)+len\('const %s = '%name\)
    # find matching end: scan to ';\\n' at depth 0
    depth=0; j=i; instr=False; esc=False
    while j<len\(h\):
        c=h[j]
        if instr:
            if esc: esc=False
            elif c=='\\\\': esc=True
            elif c=='"': instr=False
        else:
            if c=='"': instr=True
            elif c in '[{': depth+=1
            elif c in ']}': depth-=1
            elif c==';' and depth==0: break
        j+=1
    return h[i:j]
